exercises.solutionCode:
import static io.restassured.RestAssured.*;

public class SecureClient {
    public int fetchSecure(String baseUrl, String token) {
        return given()
            .header("Authorization", "Bearer " + token)
            .when()
            .get(baseUrl + "/secure")
            .then()
            .extract().statusCode();
    }
}

